(function() {
    THREE.CyberPostShader = {
        uniforms: {
            "tDiffuse": { value: null },
            "uResolution": { value: new THREE.Vector2( 1920, 1080 ) },
            "uTime": { value: 0.0 },
            "uChromaticStrength": { value: 0.0 },
            "uBarrelDistortion": { value: 0.0 },
            "uHoloScanIntensity": { value: 0.0 },
            "uHoloScanDensity": { value: 120.0 },
            "uVignetteStrength": { value: 0.0 },
            "uScreenShake": { value: 0.0 }
        },
        vertexShader: [
            "varying vec2 vUv;",
            "void main() {",
            "   vUv = uv;",
            "   gl_Position = projectionMatrix * modelViewMatrix * vec4( position, 1.0 );",
            "}"
        ].join( "\n" ),
        fragmentShader: [
            "uniform sampler2D tDiffuse;",
            "uniform vec2 uResolution;",
            "uniform float uTime;",
            "uniform float uChromaticStrength;",
            "uniform float uBarrelDistortion;",
            "uniform float uHoloScanIntensity;",
            "uniform float uHoloScanDensity;",
            "uniform float uVignetteStrength;",
            "uniform float uScreenShake;",

            "varying vec2 vUv;",

            "void main() {",
            "   vec2 uvWarped = vUv;",
            "   vec2 cc = vUv - 0.5;",
            
            "   if (uBarrelDistortion > 0.0) {",
            "       float dist = dot(cc, cc);",
            "       uvWarped = vUv + cc * dist * uBarrelDistortion;",
            "   }",

            "   if (uvWarped.x < 0.0 || uvWarped.x > 1.0 || uvWarped.y < 0.0 || uvWarped.y > 1.0) {",
            "       gl_FragColor = vec4(0.0, 0.0, 0.0, 1.0);",
            "       return;",
            "   }",

            "   vec3 color;",
            "   float totalChroma = clamp(uChromaticStrength + uScreenShake * 0.0008, 0.0, 0.002);",
            "   float edgeDist = length(cc * 2.0);",
            "   float chromaEdge = smoothstep(0.5, 1.3, edgeDist) * totalChroma;",
            "   if (chromaEdge > 0.00005) {",
            "       vec2 dir = normalize(cc + 0.0001);",
            "       color.r = texture2D(tDiffuse, uvWarped + dir * chromaEdge).r;",
            "       color.g = texture2D(tDiffuse, uvWarped).g;",
            "       color.b = texture2D(tDiffuse, uvWarped - dir * chromaEdge).b;",
            "   } else {",
            "       color = texture2D(tDiffuse, uvWarped).rgb;",
            "   }",
            "",
            "   if (uHoloScanIntensity > 0.0) {",
            "       float holoScan = smoothstep(0.0, 0.015, abs(fract((uvWarped.y * uHoloScanDensity) - uTime * 0.08) - 0.5));",
            "       color *= mix(1.0, holoScan, 0.035 * uHoloScanIntensity);",
            "       ",
            "       float sweepLine = (1.0 - smoothstep(0.0, 0.003, abs(fract(uvWarped.y - uTime * 0.05) - 0.5))) * 0.06;",
            "       color += vec3(sweepLine * 0.4, sweepLine * 0.6, sweepLine * 0.5) * uHoloScanIntensity;",
            "   }",
            "",
            "   if (uVignetteStrength > 0.0) {",
            "       float vignette = smoothstep(1.5, 0.65, length(cc * 1.6));",
            "       color *= mix(1.0, vignette, uVignetteStrength);",
            "   }",
            "",
            "   // Subtle shadow lift and color grade",
            "   color = max(color, vec3(0.008, 0.010, 0.018));",
            "   color = color * color * (3.0 - 2.0 * color);",
            "",
            "   // Very subtle film grain",
            "   float grain = fract(sin(dot(uvWarped * uResolution, vec2(12.9898, 78.233)) + uTime) * 43758.5453);",
            "   color += (grain - 0.5) * 0.012;",
            "",
            "   gl_FragColor = vec4(color, 1.0);",
            "}"
        ].join( "\n" )
    };
})();
